// narracao-cirl — Gera áudios PT-BR via ElevenLabs
// Input: { production_id, intro_narration, outro_narration, scenes:[{narration}] }
// Output: { production_id, intro_audio, outro_audio, scene_audios:[{index, path, url, public_url}] }

const http = require('http');
const https = require('https');
const crypto = require('crypto');

const ELEVENLABS_API_KEY = $env.ELEVENLABS_API_KEY;
const ELEVENLABS_VOICE_ID = $env.ELEVENLABS_VOICE_ID || 'pMsXgVXv3BLzUgSXRplE'; // Valentina PT-BR
const ELEVENLABS_MODEL = 'eleven_multilingual_v2';

const MINIO_HOST = 'host.docker.internal';
const MINIO_PUBLIC_HOST = $env.MINIO_PUBLIC_HOST || '186.202.209.88';
const MINIO_PORT = 9000;
const MINIO_BUCKET = 'cirlene-audio';
const MINIO_ACCESS = $env.MINIO_ACCESS_KEY || 'minioadmin';
const MINIO_SECRET = $env.MINIO_SECRET_KEY || 'minioadmin';

if (!ELEVENLABS_API_KEY) throw new Error('ELEVENLABS_API_KEY env var required');

const body = $input.first().json.body || $input.first().json;
const pid = body.production_id;
const introText = body.intro_narration || '';
const outroText = body.outro_narration || '';
const scenes = body.scenes || [];

if (!pid) throw new Error('production_id required');

// ── ElevenLabs TTS ───────────────────────────────────────────────
function tts(text) {
  return new Promise((resolve, reject) => {
    const payload = JSON.stringify({
      text,
      model_id: ELEVENLABS_MODEL,
      voice_settings: { stability: 0.5, similarity_boost: 0.75, style: 0.4, use_speaker_boost: true }
    });
    const opts = {
      hostname: 'api.elevenlabs.io',
      path: `/v1/text-to-speech/${ELEVENLABS_VOICE_ID}?output_format=mp3_44100_128`,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload),
        'xi-api-key': ELEVENLABS_API_KEY
      }
    };
    const req = https.request(opts, res => {
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => {
        if (res.statusCode !== 200) {
          reject(new Error(`ElevenLabs ${res.statusCode}: ${Buffer.concat(chunks).toString().slice(0,300)}`));
        } else {
          resolve(Buffer.concat(chunks));
        }
      });
    });
    req.on('error', reject);
    req.write(payload);
    req.end();
  });
}

// ── MinIO upload (AWS4 signing) ──────────────────────────────────
function hash(data) { return crypto.createHash('sha256').update(data).digest('hex'); }

function awsSign(method, bucket, key, region, accessKey, secretKey, contentType, body) {
  const now = new Date();
  const date = now.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'').slice(0,15) + 'Z';
  const dateShort = date.slice(0,8);
  const scope = `${dateShort}/${region}/s3/aws4_request`;
  const signedHeaders = 'content-type;host;x-amz-content-sha256;x-amz-date';
  const payloadHash = hash(body);
  const canonicalRequest = [
    method, `/${bucket}/${key}`, '',
    `content-type:${contentType}\nhost:${MINIO_HOST}:${MINIO_PORT}\nx-amz-content-sha256:${payloadHash}\nx-amz-date:${date}\n`,
    signedHeaders, payloadHash
  ].join('\n');
  const stringToSign = ['AWS4-HMAC-SHA256', date, scope, hash(canonicalRequest)].join('\n');
  const k1 = crypto.createHmac('sha256', 'AWS4' + secretKey).update(dateShort).digest();
  const k2 = crypto.createHmac('sha256', k1).update(region).digest();
  const k3 = crypto.createHmac('sha256', k2).update('s3').digest();
  const k4 = crypto.createHmac('sha256', k3).update('aws4_request').digest();
  const signature = crypto.createHmac('sha256', k4).update(stringToSign).digest('hex');
  return { date, scope, signedHeaders, signature, payloadHash };
}

function uploadMinio(objectKey, audioBuffer) {
  return new Promise((resolve, reject) => {
    const method = 'PUT';
    const region = 'us-east-1';
    const contentType = 'audio/mpeg';
    const sig = awsSign(method, MINIO_BUCKET, objectKey, region, MINIO_ACCESS, MINIO_SECRET, contentType, audioBuffer);
    const authHeader = `AWS4-HMAC-SHA256 Credential=${MINIO_ACCESS}/${sig.scope}, SignedHeaders=${sig.signedHeaders}, Signature=${sig.signature}`;
    const opts = {
      hostname: MINIO_HOST, port: MINIO_PORT,
      path: `/${MINIO_BUCKET}/${objectKey}`, method: 'PUT',
      headers: {
        'Content-Type': contentType,
        'Content-Length': audioBuffer.length,
        'x-amz-content-sha256': sig.payloadHash,
        'x-amz-date': sig.date,
        'Authorization': authHeader
      }
    };
    const req = http.request(opts, res => {
      let body = '';
      res.on('data', c => body += c);
      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          // Internal URL (for montagem/Docker) + public URL (for fal.ai Seedance)
          const minioInternal = MINIO_HOST + ':' + MINIO_PORT;
          const minioPublic = MINIO_PUBLIC_HOST + ':' + MINIO_PORT;
          const url = 'http://' + minioInternal + '/' + MINIO_BUCKET + '/' + objectKey;
          const public_url = 'http://' + minioPublic + '/' + MINIO_BUCKET + '/' + objectKey;
          resolve({ path: 'minio://' + MINIO_BUCKET + '/' + objectKey, url: url, public_url: public_url });
        } else {
          reject(new Error(`MinIO PUT ${res.statusCode}: ${body.slice(0,200)}`));
        }
      });
    });
    req.on('error', reject);
    req.write(audioBuffer);
    req.end();
  });
}

// ── Gerar todos os áudios em paralelo ───────────────────────────
async function genAudio(text, key) {
  if (!text || !text.trim()) return null;
  console.log(`[${pid}] ElevenLabs TTS: ${key} (${text.length} chars)`);
  const audio = await tts(text);
  const result = await uploadMinio(key, audio);
  console.log(`[${pid}] Uploaded ${audio.length} bytes → ${result.path}`);
  return result;
}

const tasks = [];

if (introText) tasks.push(genAudio(introText, `${pid}/narration-intro.mp3`).then(r => r ? ({ type: 'intro', ...r }) : null));
if (outroText) tasks.push(genAudio(outroText, `${pid}/narration-outro.mp3`).then(r => r ? ({ type: 'outro', ...r }) : null));

for (let i = 0; i < scenes.length; i++) {
  const text = scenes[i].narration || '';
  if (text) {
    tasks.push(genAudio(text, `${pid}/narration-scene-${i}.mp3`).then(r => r ? ({ type: 'scene', index: i, ...r }) : null));
  }
}

const results = (await Promise.all(tasks)).filter(Boolean);

const intro_audio = results.find(r => r.type === 'intro') || null;
const outro_audio = results.find(r => r.type === 'outro') || null;
const scene_audios = results
  .filter(r => r.type === 'scene')
  .sort((a, b) => a.index - b.index)
  .map(r => ({ index: r.index, path: r.path, url: r.url, public_url: r.public_url }));

console.log(`[${pid}] Narrações ElevenLabs OK: intro=${!!intro_audio} outro=${!!outro_audio} scenes=${scene_audios.length}`);

return [{ json: {
  production_id: pid,
  intro_audio,
  outro_audio,
  scene_audios,
  total: results.length
}}];
